using System;using System.IO;using UnityEditor;using UnityEngine;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using LWS.TruckSports.Editor;
namespace LWS.TruckFishing.Editor {
// Course geometry and vendor presentation adapters; no separate terrain or water simulation.
public static class FishingPresentationAuthoring {
 const string Folder="TruckFishing";
 public static void Install(FishingMatch match){
  var ground=Ground();var grass=Scenery("Assets/JC_LP_MegaCity/Prefabs/Nature/SM_Nature_Grass_01.prefab","River bank grass",new Vector3(1.3f,.6f,1.3f));var rocks=new GameObject[3];
  for(int i=0;i<3;i++)rocks[i]=Scenery("Assets/Layer Lab/3D Characters-Fish/Fish/Prefabs/Rock"+(char)('A'+i)+".prefab","River boulder "+i,new Vector3(1.5f,.8f,1.1f));
  var terrainMaterial=SportsEventAuthoring.Mat(Folder,"Continuous grassy bank terrain",Color.white);terrainMaterial.shader=Shader.Find("Universal Render Pipeline/Terrain/Lit");
  foreach(var stream in match.streams){var root=stream.transform;for(int n=root.childCount-1;n>=0;n--){var child=root.GetChild(n);if(child.name=="Curving grassy bank"||child.name=="Bank reed tuft"||child.name=="Submerged riverbed"||child.name=="Riverbank scenery")UnityEngine.Object.DestroyImmediate(child.gameObject);}
   var terrain=Terrain.CreateTerrainGameObject(ground);terrain.name="Continuous sculpted river bed and grassy banks";terrain.transform.SetParent(root,false);terrain.transform.localPosition=new Vector3(-18,-2,-8);var component=terrain.GetComponent<Terrain>();component.materialTemplate=terrainMaterial;component.drawInstanced=true;component.heightmapPixelError=8;component.shadowCastingMode=ShadowCastingMode.On;
   var group=new GameObject("Riverbank scenery").transform;group.SetParent(root,false);var random=new System.Random(502);
   for(int n=0;n<60;n++){int side=n%2==0?-1:1;float z=-1+(float)random.NextDouble()*29;float x=side*(8.2f+(float)random.NextDouble()*2.5f);var model=(GameObject)PrefabUtility.InstantiatePrefab(n%4==0?rocks[n%3]:grass);model.transform.SetParent(group,false);model.transform.localPosition=new Vector3(x,Height(x,z),z);model.transform.localRotation=Quaternion.Euler(0,(float)random.NextDouble()*360,0);model.transform.localScale*=.8f+(float)random.NextDouble()*.5f;}
   var camera=match.streamCameras[stream.slot].view;camera.GetUniversalAdditionalCameraData().requiresDepthTexture=true;camera.GetUniversalAdditionalCameraData().requiresColorTexture=true;
  }
 }
 static float Edge(float z)=>7.15f+.32f*Mathf.Sin(z*.28f);
 static float Height(float x,float z){float bank=Mathf.SmoothStep(0,1,Mathf.InverseLerp(Edge(z)-.4f,Edge(z)+1.5f,Mathf.Abs(x)));return Mathf.Lerp(-.7f,.65f,bank)+.11f*Mathf.PerlinNoise(x*.3f+20,z*.22f)*bank;}
 static TerrainData Ground(){string path="Assets/"+Folder+"/Models/Continuous Riverbank.asset";var data=AssetDatabase.LoadAssetAtPath<TerrainData>(path);if(data==null){data=new TerrainData();AssetDatabase.CreateAsset(data,path);}data.heightmapResolution=129;data.size=new Vector3(36,4,44);data.terrainLayers=new[]{Layer("Grass bank","Assets/RiverModeler/Demo/Viking Village/Terrain/Grass_B_BaseColor.png","Assets/RiverModeler/Demo/Viking Village/Terrain/Grass_B_Normal.png",new Vector2(4,4)),Layer("Shallow pebbled riverbed","Assets/RiverModeler/Demo/Viking Village/Terrain/Black_Sand_Rocks_B_BaseColor.png","Assets/RiverModeler/Demo/Viking Village/Terrain/Black_Sand_Rocks_B_Normal.png",new Vector2(3,3))};var h=new float[129,129];for(int z=0;z<129;z++)for(int x=0;x<129;x++)h[z,x]=(Height(-18+x/128f*36,-8+z/128f*44)+2)/4;data.SetHeights(0,0,h);data.alphamapResolution=128;var paint=new float[128,128,2];for(int z=0;z<128;z++)for(int x=0;x<128;x++){float wx=-18+x/127f*36,wz=-8+z/127f*44;float bank=Mathf.SmoothStep(0,1,Mathf.InverseLerp(Edge(wz)+.1f,Edge(wz)+1.3f,Mathf.Abs(wx)));paint[z,x,0]=bank;paint[z,x,1]=1-bank;}data.SetAlphamaps(0,0,paint);EditorUtility.SetDirty(data);return data;}
 static TerrainLayer Layer(string name,string diffuse,string normal,Vector2 tiling){string path="Assets/"+Folder+"/Materials/"+name+".terrainlayer";var layer=AssetDatabase.LoadAssetAtPath<TerrainLayer>(path);if(layer==null){layer=new TerrainLayer();AssetDatabase.CreateAsset(layer,path);}layer.diffuseTexture=AssetDatabase.LoadAssetAtPath<Texture2D>(diffuse);layer.normalMapTexture=AssetDatabase.LoadAssetAtPath<Texture2D>(normal);layer.tileSize=tiling;layer.normalScale=.35f;layer.smoothness=.08f;if(layer.diffuseTexture==null)throw new Exception("Installed riverbank texture missing: "+diffuse);EditorUtility.SetDirty(layer);return layer;}
 static GameObject Scenery(string path,string name,Vector3 size){var source=AssetDatabase.LoadAssetAtPath<GameObject>(path);if(source==null)throw new Exception("Installed river scenery missing: "+path);var holder=new GameObject(name);var model=(GameObject)PrefabUtility.InstantiatePrefab(source);model.transform.SetParent(holder.transform,false);foreach(var c in model.GetComponentsInChildren<Collider>(true))UnityEngine.Object.DestroyImmediate(c);var renderers=model.GetComponentsInChildren<Renderer>(true);if(renderers.Length==0)throw new Exception("Installed scenery has no model: "+path);var bounds=renderers[0].bounds;foreach(var r in renderers)bounds.Encapsulate(r.bounds);float scale=Mathf.Min(size.x/bounds.size.x,size.y/bounds.size.y,size.z/bounds.size.z);model.transform.localScale*=scale;model.transform.localPosition=-new Vector3(bounds.center.x,bounds.min.y,bounds.center.z)*scale;foreach(var r in renderers){var materials=r.sharedMaterials;for(int i=0;i<materials.Length;i++){var original=materials[i];if(original==null)continue;var material=SportsEventAuthoring.Mat(Folder,name+" "+i,original.HasProperty("_Color")?original.GetColor("_Color"):Color.white,.1f);material.mainTexture=original.mainTexture;if(name.Contains("boulder"))material.color=new Color(.38f,.42f,.37f);if(name.Contains("grass")){material.SetFloat("_AlphaClip",1);material.SetFloat("_Cutoff",.35f);material.SetFloat("_Cull",0);material.EnableKeyword("_ALPHATEST_ON");}materials[i]=material;}r.sharedMaterials=materials;}var result=PrefabUtility.SaveAsPrefabAsset(holder,"Assets/"+Folder+"/Prefabs/"+name+".prefab");UnityEngine.Object.DestroyImmediate(holder);return result;}
}
}
